const form = $input.first().json;

  const asList = (value) => {
    if (Array.isArray(value)) return value.map(String).map((item) => item.trim()).filter(Boolean);
    if (typeof value !== 'string') return [];
    return value.split(',').map((item) => item.trim()).filter(Boolean);
  };

  const providers = {
    OpenAI: {
      id: 'openai',
      nodeSuffix: 'OpenAI Chat Model',
    },
    Anthropic: {
      id: 'anthropic',
      nodeSuffix: 'Anthropic Chat Model',
    },
    'Google Gemini': {
      id: 'google',
      nodeSuffix: 'Google Gemini Chat Model',
    },
  };
  const roleNodes = {
    transformation: 'Transformation Generation',
    semantic_test: 'Semantic Test Generation',
    source_diagnosis: 'Source Diagnosis',
    refinement: 'Refinement',
  };
  const selectedModel = (role, providerLabel) => {
    const provider = providers[providerLabel];
    if (!provider) throw new Error(`Select a supported provider for ${role}`);
    const nodeName = `${roleNodes[role]} - ${provider.nodeSuffix}`;
    const parameters = $(nodeName).params;
    const configuredModel = provider.id === 'google' ? parameters.modelName : parameters.model;
    const model = configuredModel && typeof configuredModel === 'object'
      ? configuredModel.value
      : configuredModel;
    if (typeof model !== 'string' || !model.trim()) {
      throw new Error(`Select a model in the built-in selector of ${nodeName}`);
    }
    return {
      provider: provider.id,
      model: model.trim(),
      configuration_node: nodeName,
    };
  };

  const strategies = ['only_prompt', 'few_shot', 'grammar', 'few_shots_AND_grammar'];
  if (!strategies.includes(form.transformation_strategy)) {
    throw new Error('Select a supported Transformation Generation strategy');
  }
  if (!strategies.includes(form.semantic_test_strategy)) {
    throw new Error('Select a supported Semantic Test Generation strategy');
  }

  const languageOptions = {
    ETL: 'etl',
    ATL: 'atl',
    'QVT-O': 'qvto',
    Reactions: 'reactions',
  };
  const languages = [...new Set(asList(form.languages).map((label) => languageOptions[label]))];
  if (languages.length === 0 || languages.some((language) => !language)) {
    throw new Error('Select at least one supported language');
  }

  const refinementOptions = [0, 1, 2, 3, 4, 5];
  const maxRefinementIterations = Number(form.max_refinement_iterations);
  if (!refinementOptions.includes(maxRefinementIterations)) {
    throw new Error('Refinement iterations must be selected from 0 through 5');
  }

  const stageFields = [
    'test_generation',
    'test_extraction',
    'technical_validation',
    'reference_validation',
    'transformation_generation',
    'syntax_validation',
    'semantic_execution',
    'source_diagnosis',
    'parser_feedback',
    'semantic_feedback',
    'test_refinement',
    'transformation_refinement',
  ];
  const stages = {};
  for (const stage of stageFields) {
    if (!['Enabled', 'Disabled'].includes(form[stage])) {
      throw new Error(`${stage} must be explicitly Enabled or Disabled`);
    }
    stages[stage] = form[stage] === 'Enabled';
  }

  const root = String(form.n8n_workflow_root || '/data/repository/workflows/n8n').replace(/\/$/, '');
  if (!root.startsWith('/data/') || root.includes('..')) {
    throw new Error('Workflow root must be a contained read-only mount below /data');
  }

  const llms = {
    transformation: {
      ...selectedModel('transformation', form.transformation_provider),
      strategy: form.transformation_strategy,
    },
    semantic_test: {
      ...selectedModel('semantic_test', form.semantic_test_provider),
      strategy: form.semantic_test_strategy,
    },
    source_diagnosis: selectedModel('source_diagnosis', form.source_diagnosis_provider),
    refinement: selectedModel('refinement', form.refinement_provider),
  };

  const disabledStages = stageFields.filter((stage) => !stages[stage]);
  const pipelineVariant = disabledStages.length === 0
    ? 'full'
    : `ablation:${disabledStages.join('+')}`;
  const taskDefaults = {
    etl: 'Tree2Graph',
    atl: 'NetworkToGraph_All',
    qvto: 'Mappings',
    reactions: 'FamiliesToPersons_CreatedFather',
  };
  const labels = {
    etl: 'ETL',
    atl: 'ATL',
    qvto: 'QVTO',
    reactions: 'Reactions',
  };

  const runSpecs = languages.map((language) => {
    const label = labels[language];
    const transformationWorkflow = language === 'reactions'
      ? `${root}/transformations/workflows/updated_reactions_workflow/generate_reactions/LLM4MTL_Generate_Reactions_for_all_Configurations.json`
      : `${root}/transformations/workflows/${language}_variants/Prompting_${label}_*_${llms.transformation.strategy}.json`;
    return {
      language,
      language_label: label,
      task: taskDefaults[language],
      transformation_model: llms.transformation.model,
      test_generation_model: llms.semantic_test.model,
      transformation_strategy: llms.transformation.strategy,
      test_generation_strategy: llms.semantic_test.strategy,
      seed: 1,
      pipeline_variant: pipelineVariant,
      test_generation_workflow: `${root}/tests/workflows/${language}_variants/test_generation/Prompting_tests_${label}_*_${llms.semantic_test.strategy}.json`,
      transformation_generation_workflow: transformationWorkflow,
      diagnosis_workflow: `${root}/subworkflows/diagnosis/llm-diagnosis.json`,
    };
  });

  return [{
    json: {
      config: {
        llms,
        max_refinement_iterations: maxRefinementIterations,
        stages,
        pipeline_variant: pipelineVariant,
      },
      run_specs: runSpecs,
      run_index: 0,
      current: {
        ...runSpecs[0],
        run_id: null,
        suite_id: null,
        refinement_iteration: 0,
        generation_purpose: 'initial',
        has_transformation: false,
        timeline: [],
        terminal_status: null,
        terminal_reason: null,
      },
      results: [],
      action: null,
      completed_action: null,
      last_result: null,
    },
  }];

const state = structuredClone($input.first().json);
const flags = state.config.stages;
const maxRefinements = state.config.max_refinement_iterations;

const actionFlag = {
  generate_tests: 'test_generation',
  extract: 'test_extraction',
  technical: 'technical_validation',
  reference: 'reference_validation',
  generate_transformations: 'transformation_generation',
  syntax: 'syntax_validation',
  execution: 'semantic_execution',
  diagnose: 'source_diagnosis',
};
const stageIds = {
  extract: 'extract',
  technical: 'technical-validation',
  reference: 'reference-validation',
  syntax: 'syntax-validation',
  execution: 'execution',
};

function choose(action) {
  state.action = action;
  state.stage_id = stageIds[action] || null;
  state.subworkflow_path = null;
  state.subworkflow_input = null;
  if (action === 'generate_tests') {
    state.subworkflow_path = state.current.test_generation_workflow;
    state.subworkflow_input = {
      language: state.current.language,
      task: state.current.task,
      provider: (state.current.refinement_iteration > 0 ? state.config.llms.refinement : state.config.llms.semantic_test).provider,
      model: (state.current.refinement_iteration > 0 ? state.config.llms.refinement : state.config.llms.semantic_test).model,
      strategy: state.config.llms.semantic_test.strategy,
      llm_role: state.current.refinement_iteration > 0 ? 'refinement' : 'semantic_test',
      run_id: state.current.run_id,
      refinement_iteration: state.current.refinement_iteration,
      refinement_reason: state.current.refinement_reason || null,
    };
  } else if (action === 'generate_transformations') {
    state.subworkflow_path = state.current.transformation_generation_workflow;
    state.subworkflow_input = {
      language: state.current.language,
      task: state.current.task,
      provider: (state.current.refinement_iteration > 0 ? state.config.llms.refinement : state.config.llms.transformation).provider,
      model: (state.current.refinement_iteration > 0 ? state.config.llms.refinement : state.config.llms.transformation).model,
      strategy: state.config.llms.transformation.strategy,
      llm_role: state.current.refinement_iteration > 0 ? 'refinement' : 'transformation',
      run_id: state.current.run_id,
      refinement_iteration: state.current.refinement_iteration,
      refinement_reason: state.current.refinement_reason || null,
    };
  } else if (action === 'diagnose') {
    state.subworkflow_path = state.current.diagnosis_workflow;
    state.subworkflow_input = {
      run_id: state.current.run_id,
      outcome_code: 'SEMANTIC_EXECUTION_FAILED',
      execution_attempt: state.current.execution_result.attempt,
      diagnosis_provider: state.config.llms.source_diagnosis.provider,
      model: state.config.llms.source_diagnosis.model,
      llm_role: 'source_diagnosis',
      failure_report_path: state.current.failure_report_path,
    };
  }
}

function finish(status, reason) {
  state.current.terminal_status = status;
  state.current.terminal_reason = reason;
  choose('final');
}

function nextEnabled(actions, emptyReason) {
  for (const action of actions) {
    if (flags[actionFlag[action]]) {
      choose(action);
      return;
    }
  }
  finish('incomplete', emptyReason);
}

function afterTestArtifact() {
  nextEnabled(
    ['extract', 'technical', 'reference', 'generate_transformations', 'syntax', 'execution'],
    'NO_POST_TEST_GENERATION_STAGE_ENABLED',
  );
}

function afterValidatedTests() {
  if (state.current.has_transformation) {
    nextEnabled(['syntax', 'execution'], 'NO_TRANSFORMATION_EVALUATION_STAGE_ENABLED');
    return;
  }
  nextEnabled(
    ['generate_transformations', 'syntax', 'execution'],
    'NO_TRANSFORMATION_STAGE_ENABLED',
  );
}

function requestRefinement(target, reason) {
  const refinementFlag = target === 'tests' ? flags.test_refinement : flags.transformation_refinement;
  const generationFlag = target === 'tests' ? flags.test_generation : flags.transformation_generation;
  if (!refinementFlag || !generationFlag) {
    finish('completed_with_failures', `${reason}:REFINEMENT_DISABLED`);
    return;
  }
  if (state.current.refinement_iteration >= maxRefinements) {
    finish('completed_with_failures', `${reason}:REFINEMENT_LIMIT_REACHED`);
    return;
  }
  state.current.refinement_iteration += 1;
  state.current.suite_id = `${state.current.run_id}_${String(state.current.refinement_iteration).padStart(3, '0')}`;
  state.current.refinement_reason = reason;
  state.current.generation_purpose = `${target}_refinement`;
  choose(target === 'tests' ? 'generate_tests' : 'generate_transformations');
}

function recordStage(action, result) {
  state.current.timeline.push({
    action,
    stage: result.stage || null,
    status: result.status || null,
    outcome_code: result.outcome_code || null,
    attempt: result.attempt || null,
    counts: result.counts || {},
    artifacts: result.artifacts || {},
  });
}

const completed = state.completed_action;
const result = state.last_result || {};

if (!completed) {
  choose('create_run');
} else if (completed === 'create_run') {
  if (typeof result.run_id !== 'string' || !result.run_id) {
    throw new Error('POST /runs did not return run_id');
  }
  state.current.run_id = result.run_id;
  state.current.suite_id = `${result.run_id}_000`;
  nextEnabled(
    ['generate_tests', 'extract', 'technical', 'reference', 'generate_transformations', 'syntax', 'execution'],
    'ALL_PIPELINE_STAGES_DISABLED',
  );
} else if (completed === 'generate_tests') {
  state.current.timeline.push({
    action: 'generate_tests',
    refinement_iteration: state.current.refinement_iteration,
    purpose: state.current.generation_purpose,
    workflow: state.current.test_generation_workflow,
  });
  afterTestArtifact();
} else if (completed === 'extract') {
  recordStage(completed, result);
  if (result.outcome_code === 'EXTRACTED') {
    nextEnabled(
      ['technical', 'reference', 'generate_transformations', 'syntax', 'execution'],
      'NO_STAGE_AFTER_EXTRACTION_ENABLED',
    );
  } else if (result.outcome_code === 'TEST_SPEC_INVALID') {
    requestRefinement('tests', result.outcome_code);
  } else if (result.outcome_code === 'INFRASTRUCTURE_ERROR') {
    finish('failed', 'EXTRACTION_INFRASTRUCTURE_ERROR');
  } else {
    finish('incomplete', result.outcome_code || 'UNKNOWN_EXTRACTION_OUTCOME');
  }
} else if (completed === 'technical') {
  recordStage(completed, result);
  if (result.outcome_code === 'TECH_VALID') {
    nextEnabled(
      ['reference', 'generate_transformations', 'syntax', 'execution'],
      'NO_STAGE_AFTER_TECHNICAL_VALIDATION_ENABLED',
    );
  } else if (['TECH_COMPILE_FAILED', 'TECH_EXEC_FAILED', 'TEST_SPEC_INVALID'].includes(result.outcome_code)) {
    requestRefinement('tests', result.outcome_code);
  } else if (result.outcome_code === 'INFRASTRUCTURE_ERROR') {
    finish('failed', 'TECHNICAL_VALIDATION_INFRASTRUCTURE_ERROR');
  } else {
    finish('incomplete', result.outcome_code || 'UNKNOWN_TECHNICAL_OUTCOME');
  }
} else if (completed === 'reference') {
  recordStage(completed, result);
  if (result.outcome_code === 'REFERENCE_VALIDATED') {
    afterValidatedTests();
  } else if (result.outcome_code === 'REFERENCE_VALIDATION_FAILED') {
    requestRefinement('tests', result.outcome_code);
  } else if (result.outcome_code === 'INFRASTRUCTURE_ERROR') {
    finish('failed', 'REFERENCE_VALIDATION_INFRASTRUCTURE_ERROR');
  } else {
    finish('incomplete', result.outcome_code || 'UNKNOWN_REFERENCE_OUTCOME');
  }
} else if (completed === 'generate_transformations') {
  state.current.has_transformation = true;
  state.current.timeline.push({
    action: 'generate_transformations',
    refinement_iteration: state.current.refinement_iteration,
    purpose: state.current.generation_purpose,
    workflow: state.current.transformation_generation_workflow,
  });
  nextEnabled(['syntax', 'execution'], 'NO_STAGE_AFTER_TRANSFORMATION_GENERATION_ENABLED');
} else if (completed === 'syntax') {
  recordStage(completed, result);
  if (result.outcome_code === 'SYNTAX_VALID') {
    nextEnabled(['execution'], 'SEMANTIC_EXECUTION_DISABLED');
  } else if (result.outcome_code === 'SYNTAX_INVALID') {
    if (flags.parser_feedback) {
      requestRefinement('transformations', result.outcome_code);
    } else {
      finish('completed_with_failures', 'SYNTAX_INVALID:PARSER_FEEDBACK_DISABLED');
    }
  } else if (result.outcome_code === 'INFRASTRUCTURE_ERROR') {
    finish('failed', 'SYNTAX_VALIDATION_INFRASTRUCTURE_ERROR');
  } else {
    finish('incomplete', result.outcome_code || 'UNKNOWN_SYNTAX_OUTCOME');
  }
} else if (completed === 'execution') {
  recordStage(completed, result);
  state.current.execution_result = result;
  if (result.outcome_code === 'SEMANTIC_PASSED') {
    finish('completed', 'SEMANTIC_PASSED');
  } else if (result.outcome_code === 'SEMANTIC_EXECUTION_FAILED') {
    const failureReport = result.artifacts?.failure_report_path || result.artifacts?.failure_report;
    if (flags.source_diagnosis && failureReport) {
      state.current.failure_report_path = failureReport;
      choose('diagnose');
    } else if (flags.source_diagnosis) {
      finish('incomplete', 'SOURCE_DIAGNOSIS_EVIDENCE_NOT_EXPOSED');
    } else {
      requestRefinement('transformations', 'SEMANTIC_EXECUTION_FAILED_WITHOUT_DIAGNOSIS');
    }
  } else if (result.outcome_code === 'INFRASTRUCTURE_ERROR') {
    finish('failed', 'SEMANTIC_EXECUTION_INFRASTRUCTURE_ERROR');
  } else {
    finish('incomplete', result.outcome_code || 'UNKNOWN_EXECUTION_OUTCOME');
  }
} else if (completed === 'diagnose') {
  const verdict = Array.isArray(result.items) ? result.items[0] || {} : result;
  state.current.timeline.push({
    action: 'diagnose',
    classification: verdict.classification || null,
    confidence: verdict.confidence || null,
    test_case_id: verdict.test_case_id || null,
    assertion_id: verdict.assertion_id || null,
  });
  if (!flags.semantic_feedback && ['transformation_defect', 'test_defect'].includes(verdict.classification)) {
    finish('completed_with_failures', `${verdict.classification.toUpperCase()}:SEMANTIC_FEEDBACK_DISABLED`);
  } else if (verdict.classification === 'transformation_defect') {
    requestRefinement('transformations', 'DIAGNOSED_TRANSFORMATION_DEFECT');
  } else if (verdict.classification === 'test_defect') {
    requestRefinement('tests', 'DIAGNOSED_TEST_DEFECT');
  } else if (verdict.classification === 'ambiguous') {
    finish('completed_with_failures', 'AMBIGUOUS_SOURCE_DIAGNOSIS');
  } else {
    finish('incomplete', 'INVALID_SOURCE_DIAGNOSIS_RESULT');
  }
} else if (completed === 'final') {
  state.results.push({
    run_id: state.current.run_id,
    language: state.current.language,
    task: state.current.task,
    status: state.current.terminal_status || 'incomplete',
    reason: state.current.terminal_reason || 'NO_TERMINAL_REASON',
    refinement_iterations: state.current.refinement_iteration,
    suite_id: state.current.suite_id,
    timeline: state.current.timeline,
    artifacts: result,
  });
  state.run_index += 1;
  if (state.run_index >= state.run_specs.length) {
    choose('complete');
  } else {
    const next = state.run_specs[state.run_index];
    state.current = {
      ...next,
      run_id: null,
      suite_id: null,
      refinement_iteration: 0,
      generation_purpose: 'initial',
      has_transformation: false,
      timeline: [],
      terminal_status: null,
      terminal_reason: null,
    };
    state.completed_action = null;
    state.last_result = null;
    choose('create_run');
  }
} else {
  throw new Error(`Unknown completed action: ${completed}`);
}

state.completed_action = null;
state.last_result = null;
return [{ json: state }];

const state = $('State Machine').first().json;
  const providerNodeTypes = {
    openai: '@n8n/n8n-nodes-langchain.lmChatOpenAi',
    anthropic: '@n8n/n8n-nodes-langchain.lmChatAnthropic',
    google: '@n8n/n8n-nodes-langchain.lmChatGoogleGemini',
  };
  const providerNodeNames = {
    openai: 'OpenAI Chat Model',
    anthropic: 'Anthropic Chat Model',
    google: 'Google Gemini Chat Model',
  };
  const provider = state.subworkflow_input?.provider || state.subworkflow_input?.diagnosis_provider;
  const model = state.subworkflow_input?.model;
  const strategy = state.subworkflow_input?.strategy;
  const expectedType = providerNodeTypes[provider];
  if (!expectedType || typeof model !== 'string' || !model.trim()) {
    throw new Error('Subworkflow execution requires a configured provider and model');
  }

  const candidates = [];
  for (const item of $input.all()) {
    const raw = item.json.workflow_text;
    if (typeof raw !== 'string' || !raw.trim()) continue;
    try {
      const candidate = JSON.parse(raw);
      if (
        Array.isArray(candidate.nodes)
        && candidate.connections
        && candidate.nodes.some((node) => node.type === expectedType)
      ) {
        candidates.push(candidate);
      }
    } catch (error) {
      throw new Error(`Invalid subworkflow JSON at ${state.subworkflow_path}: ${error.message}`);
    }
  }
  if (candidates.length === 0) {
    throw new Error(`No ${provider} subworkflow matched ${state.subworkflow_path}`);
  }
  candidates.sort((left, right) => String(left.name || '').localeCompare(String(right.name || '')));
  const workflow = candidates[0];

  const modelNode = workflow.nodes.find((node) => node.type === expectedType);
  const currentModelSetting = provider === 'google'
    ? modelNode.parameters.modelName
    : modelNode.parameters.model;
  const originalModel = currentModelSetting && typeof currentModelSetting === 'object'
    ? currentModelSetting.value
    : currentModelSetting;
  if (provider === 'google') {
    modelNode.parameters.modelName = currentModelSetting && typeof currentModelSetting === 'object'
      ? { ...currentModelSetting, value: model, cachedResultName: model }
      : model;
  } else {
    modelNode.parameters.model = currentModelSetting && typeof currentModelSetting === 'object'
      ? { ...currentModelSetting, value: model, cachedResultName: model }
      : model;
  }

  const artifactModel = model
    .replace(/^models\//, '')
    .replace(/[^A-Za-z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  const artifactPathPattern = /\/(?:responses|prompts)\/([^/]+)\//;
  const originalArtifactMatch = JSON.stringify(workflow).match(artifactPathPattern);
  const replaceArtifactPaths = (value) => {
    if (typeof value === 'string') {
      return value.replace(
        /\/(responses|prompts)\/[^/]+\//g,
        `/$1/${artifactModel}/`,
      );
    }
    if (Array.isArray(value)) return value.map(replaceArtifactPaths);
    if (value && typeof value === 'object') {
      return Object.fromEntries(
        Object.entries(value).map(([key, nested]) => [key, replaceArtifactPaths(nested)]),
      );
    }
    return value;
  };
  for (const node of workflow.nodes) {
    if (node !== modelNode) node.parameters = replaceArtifactPaths(node.parameters);
  }
  if (originalArtifactMatch && typeof workflow.name === 'string') {
    workflow.name = workflow.name.replace(originalArtifactMatch[1], artifactModel);
  }

  const diagnosisProvenance = workflow.nodes.find((node) => node.name === 'Attach Diagnosis Provenance');
  if (
    diagnosisProvenance
    && typeof diagnosisProvenance.parameters?.jsCode === 'string'
    && typeof originalModel === 'string'
  ) {
    diagnosisProvenance.parameters.jsCode = diagnosisProvenance.parameters.jsCode.replaceAll(
      originalModel,
      model,
    );
  }

  const matrixModels = workflow.nodes.find((node) => node.name === 'Define LLM models to use');
  const matrixStrategies = workflow.nodes.find((node) => node.name === 'Define Strategies');
  if (matrixModels && matrixStrategies) {
    if (typeof strategy !== 'string') {
      throw new Error('The Reactions generation matrix requires a selected strategy');
    }
    const strategyFlags = {
      only_prompt: { Few_shot: false, Grammar: false, Helper_methods: false },
      grammar: { Few_shot: false, Grammar: true, Helper_methods: false },
      few_shot: { Few_shot: true, Grammar: false, Helper_methods: false },
      few_shots_AND_grammar: { Few_shot: true, Grammar: true, Helper_methods: false },
    }[strategy];
    if (!strategyFlags) throw new Error(`Unsupported Reactions strategy: ${strategy}`);
    matrixModels.parameters.jsonOutput = JSON.stringify({
      llms: [{
        name: artifactModel,
        node: providerNodeNames[provider],
      }],
    }, null, 2);
    matrixStrategies.parameters.jsonOutput = JSON.stringify({
      strategies: [{
        name: strategy,
        ...strategyFlags,
      }],
    }, null, 2);
    const selectedChain = workflow.connections[modelNode.name]
      ?.ai_languageModel
      ?.flat()
      ?.find((connection) => connection.type === 'ai_languageModel')
      ?.node;
    const providerIf = workflow.nodes.find((node) => {
      if (node.type !== 'n8n-nodes-base.if' || !selectedChain) return false;
      const outputs = workflow.connections[node.name]?.main || [];
      return outputs.some((connections) => connections.some(
        (connection) => connection.node === selectedChain,
      ));
    });
    if (!providerIf) throw new Error(`Reactions workflow has no routing branch for ${provider}`);
    const llmCondition = providerIf.parameters.conditions.conditions.find(
      (condition) => condition.leftValue?.includes('llmName'),
    );
    if (!llmCondition) throw new Error(`Reactions provider branch has no llmName condition: ${provider}`);
    llmCondition.rightValue = artifactModel;
  }

  const callableTrigger = workflow.nodes.find(
    (node) => node.type === 'n8n-nodes-base.executeWorkflowTrigger',
  );
  if (!callableTrigger) {
    const manualTrigger = workflow.nodes.find(
      (node) => node.type === 'n8n-nodes-base.manualTrigger',
    );
    if (!manualTrigger) {
      throw new Error(`Subworkflow has no supported start node: ${state.subworkflow_path}`);
    }
    manualTrigger.type = 'n8n-nodes-base.executeWorkflowTrigger';
    manualTrigger.typeVersion = 1.1;
    manualTrigger.parameters = { inputSource: 'passthrough' };
  }
  workflow.active = false;

  return [{
    json: {
      ...state,
      ...(state.subworkflow_input || {}),
      workflow_json: workflow,
    },
  }];

const state = $('State Machine').first().json;
const items = $input.all();
const lastResult = items.length === 1
  ? items[0].json
  : { items: items.map((item) => item.json) };
return [{
  json: {
    ...state,
    completed_action: state.action,
    last_result: lastResult,
  },
}];

const state = $input.first().json;
const statuses = state.results.map((result) => result.status);
const status = statuses.includes('failed')
  ? 'failed'
  : statuses.includes('completed_with_failures')
    ? 'completed_with_failures'
    : statuses.includes('incomplete')
      ? 'incomplete'
      : 'completed';
return [{
  json: {
    status,
    run_count: state.results.length,
    languages: state.results.map((result) => result.language),
    pipeline_variant: state.config.pipeline_variant,
    results: state.results,
  },
}];
